def solve_game(N):
    if N == 1:
        # A writes 1 and wins immediately.
        return 'A'

    # Win[n] is True if the player whose turn it is at state n wins, False otherwise.
    # We only care about n < N.
    Win = {}

    # Iterate backwards from N-1 down to 1
    for n in range(N - 1, 0, -1):
        is_winning = False

        # Potential moves: n+1 and 2n
        moves = []
        if n + 1 <= N:
            moves.append(n + 1)
        if 2 * n <= N:
            moves.append(2 * n)

        # Check winning condition for current player (n)
        # 1. Can move directly to N?
        if N in moves:
            is_winning = True
        else:
            # 2. Does there exist a move n' such that the opponent (who faces n') loses?
            can_move_to_losing_position = False
            for n_prime in moves:
                if n_prime == N:
                    # This case is handled above, but defensively check for recursion termination if structure changes
                    continue

                # The player whose turn it is at n wins if they can move to n' where Win[n'] is False (Losing for next player).
                if not Win[n_prime]:
                    can_move_to_losing_position = True
                    break

            is_winning = can_move_to_losing_position

        Win[n] = is_winning

    # The game starts at n=1, and it is B's turn.
    # A plays 1. B faces 1. If Win[1] is True, B wins (Type B). If Win[1] is False, A wins (Type A).

    # Wait, re-reading the problem: "Player A starts the game by writing the number 1."
    # This means A makes the move 0->1 (implicitly). The actual game starts at state 1, and it is B's turn.
    # If Win[1] is True, the player whose turn it is (B) wins -> Type B.
    # If Win[1] is False, the player whose turn it is (B) loses -> Type A.

    if Win[1]:
        return 'B' # B wins
    else:
        return 'A' # A wins

# Calculate for N = 1 to 100
results = {}
for N in range(1, 101):
    results[N] = solve_game(N)

# Prepare results for logging
output = "N | Type\n"
output += "---|---\n"
for N, type_ in results.items():
    output += f"{N:<2} | {type_}\n"

print(output)
